class FastInt32Array {
    constructor() {
        this.a = new Int32Array(10);
        this.b = new Int32Array(10);
    }
    get(idx) {
        if (idx < 0) {
            idx = -idx - 1;
            return this.b[idx];
        }
        else {
            return this.a[idx];
        }
    }
    set(idx, value) {
        if (idx < 0) {
            idx = -idx - 1;
            if (idx >= this.b.length) {
                const arr = this.b;
                this.b = new Int32Array(arr.length * 2);
                this.b.set(arr);
            }
            this.b[idx] = value;
        }
        else {
            if (idx >= this.a.length) {
                const arr = this.a;
                this.a = new Int32Array(arr.length * 2);
                this.a.set(arr);
            }
            this.a[idx] = value;
        }
    }
}
